fn process_order(order: Order) -> Result<(), Error> {
    if order.is_valid() {
        match order.payment_status {
            PaymentStatus::Paid => {
                for item in &order.items {
                    if item.in_stock() {
                        if let Some(ref supplier) = item.supplier {
                            supplier.request_shipment(item)?;
                        } else {
                            return Err(Error::NoSupplier);
                        }
                    } else {
                        return Err(Error::OutOfStock);
                    }
                }
                Ok(())
            }
            PaymentStatus::Unpaid => Err(Error::Unpaid),
        }
    } else {
        Err(Error::InvalidOrder)
    }
}
